function event(
  host: Host,
  source: string,
  session: string,
  usageId: string,
  timestamp?: unknown,
): ObserveBatchEvent {
  const validTime = sourceTime(timestamp);
  return {
    kind: "session",
    name: "model_usage",
    session,
    ...(validTime ? { ts: timestamp } : {}),
    attrs: {
      model_usage_version: "1",
      host,
      usage_source: source,
      usage_id: usageId,
      usage_time_basis: validTime ? "source" : "observed",
      usage_coverage: "partial",
