      if (!data.stop_hook_active) {
        debug(SOURCE, "Stop hook - capturing session summary");
        captureSessionSummary(cwd, sessionId, data.transcript_path);
      }
    }

    emitHookResult({ continue: true });
  } catch (err) {
    debug(SOURCE, `Error: ${err}`);
    emitHookResult({ continue: true });
  }
}

