import { existsSync, mkdirSync, appendFileSync } from "fs";
import { join } from "path";
import { anchoredRoot } from "./anchor.js";

export type LogLevel = "debug" | "info" | "warn" | "error";

interface LogEntry {
  timestamp: string;
  level: LogLevel;
  source: string;
  message: string;
  duration?: number;
  data?: unknown;
}

interface TimingEntry {
  start: number;
  label: string;
}

export class Logger {
  private enabled: boolean;
  private source: string;
  private cwd: string;
  private logDir: string;
  private logFile: string;
  private entries: LogEntry[] = [];
  private timings: Map<string, TimingEntry> = new Map();
  private sessionStart: number;

  constructor(source: string, cwd?: string) {
    this.source = source;
    this.cwd = cwd || process.cwd();
    // Resolve to the canonical project root so logs land alongside the
    // real .aide/ store, not in a stray subdir the harness launched from.
    const { root, hasMarker } = anchoredRoot(this.cwd);
    // Set debugLogCwd so isDebugEnabled() can check the sentinel file at
    // the resolved root.
    setDebugCwd(root);
    // No marker means no project here, and creating .aide/_logs would plant
    // one wherever a hook happened to run. Disabling covers every write:
    // they all check `enabled` first.
    this.enabled = hasMarker && isDebugEnabled();
    this.logDir = join(root, ".aide", "_logs");
    this.logFile = join(this.logDir, "startup.log");
    this.sessionStart = Date.now();

    if (this.enabled) {
      this.ensureLogDir();
    }
  }

  /**
   * Check if logging is enabled
   */
  isEnabled(): boolean {
    return this.enabled;
  }

  /**
   * Ensure log directory exists
   */
  private ensureLogDir(): void {
    if (!existsSync(this.logDir)) {
      try {
        mkdirSync(this.logDir, { recursive: true });
      } catch {
        // Disable logging if we can't create directory
        this.enabled = false;
      }
    }
  }

  /**
   * Format timestamp for logging
   */
  private formatTimestamp(): string {
    return new Date().toISOString();
  }

  /**
   * Format duration in human-readable form
   */
  private formatDuration(ms: number): string {
    if (ms < 1) return "<1ms";
    if (ms < 1000) return `${Math.round(ms)}ms`;
    return `${(ms / 1000).toFixed(2)}s`;
  }

  /**
   * Add a log entry
   */
  private addEntry(
    level: LogLevel,
    message: string,
    duration?: number,
    data?: unknown,
  ): void {
    if (!this.enabled) return;

    this.entries.push({
      timestamp: this.formatTimestamp(),
      level,
      source: this.source,
      message,
      duration,
      data,
    });
  }

  /**
   * Log a debug message
   */
  debug(message: string, data?: unknown): void {
    this.addEntry("debug", message, undefined, data);
  }

  /**
   * Log an info message
   */
  info(message: string, data?: unknown): void {
    this.addEntry("info", message, undefined, data);
  }

  /**
   * Log a warning
   */
  warn(message: string, data?: unknown): void {
    this.addEntry("warn", message, undefined, data);
  }

  /**
   * Log an error
   */
  error(message: string, data?: unknown): void {
    this.addEntry("error", message, undefined, data);
  }

  /**
   * Start timing an operation
   */
  start(label: string): void {
    if (!this.enabled) return;

    this.timings.set(label, {
      start: performance.now(),
      label,
    });
    this.addEntry("debug", `→ ${label}`);
  }

  /**
   * End timing an operation and log duration
   */
  end(label: string, data?: unknown): number {
    if (!this.enabled) return 0;

    const timing = this.timings.get(label);
    if (!timing) {
      this.warn(`end() called for unknown timing: ${label}`);
      return 0;
    }

    const duration = performance.now() - timing.start;
    this.timings.delete(label);
    this.addEntry("info", `← ${label}`, duration, data);
    return duration;
  }

  /**
   * Time an operation (sync or async)
   */
  async time<T>(label: string, fn: () => T | Promise<T>): Promise<T> {
    this.start(label);
    try {
      const result = await fn();
      this.end(label);
      return result;
    } catch (err) {
      this.end(label, { error: String(err) });
      throw err;
    }
  }

  /**
   * Format entries for file output
   */
  private formatEntries(): string {
    const lines: string[] = [];
    const sessionDuration = Date.now() - this.sessionStart;

    lines.push("");
    lines.push(`${"=".repeat(60)}`);
    lines.push(
      `[${this.source}] Session started at ${new Date(this.sessionStart).toISOString()}`,
    );
    lines.push(`${"=".repeat(60)}`);

    for (const entry of this.entries) {
      const levelTag = entry.level.toUpperCase().padEnd(5);
      const durationStr =
        entry.duration !== undefined
          ? ` (${this.formatDuration(entry.duration)})`
          : "";
      lines.push(
        `${entry.timestamp} ${levelTag} ${entry.message}${durationStr}`,
      );

      if (entry.data) {
        const dataStr = JSON.stringify(entry.data, null, 2)
          .split("\n")
          .map((l) => `    ${l}`)
          .join("\n");
        lines.push(dataStr);
      }
    }

    lines.push(`${"─".repeat(60)}`);
    lines.push(`Total: ${this.formatDuration(sessionDuration)}`);
    lines.push("");

    return lines.join("\n");
  }

  /**
   * Flush all log entries to file
   */
  flush(): void {
    if (!this.enabled || this.entries.length === 0) return;

    try {
      this.ensureLogDir();
      appendFileSync(this.logFile, this.formatEntries());
      this.entries = [];
    } catch {
      // Silently fail - logging should not break the hook
    }
  }

  /**
   * Get the main log file path
   */
  getLogFile(): string {
    return this.logFile;
  }

  /**
   * Create a child logger with a sub-source name
   */
  child(subSource: string): Logger {
    const childLogger = new Logger(`${this.source}:${subSource}`, this.cwd);
    return childLogger;
